# Synth Templates — catalog builder. Writes catalog.json from the compact table below.
# Fields: id | mode | essentials (what makes it that sound) | teaches (the technique) | tier (1 foundation, 2 core, 3 advanced)
import json, re
F = {}
def fam(name, note):
    F[name] = {"note": note, "items": []}
    return name
def t(f, name, mode, ess, teaches, tier, classics=""):
    F[f]["items"].append({"id": re.sub(r"[^a-z0-9]+","-",name.lower()).strip("-"),
        "name": name, "mode": mode, "essentials": ess, "teaches": teaches, "tier": tier, "classics": classics})

f = fam("Bass", "The low end. Mono almost always; the filter envelope and the decay shape are the whole character.")
t(f,"Sub Bass","mono","Sine (or triangle), no filter, instant attack, held sustain, short release. One octave down.","Pure fundamental; why sub needs no harmonics",1,"any 808 sub")
t(f,"808 Bass","mono","Sine, pitch envelope drops ~1 octave in 20–60 ms, long amp decay (1–3 s), light saturation for upper harmonics.","Pitch envelope as punch; decay as length",1,"TR-808 kick-as-bass")
t(f,"House Bass","mono","Square (or pulse) + sub, resonant LPF, filter env: instant attack, short decay, zero sustain. Amp: fast attack, medium decay.","Percussive filter envelope; the pluck is in the filter not the amp",1,"classic Chicago / French house")
t(f,"Acid Bass","mono legato","Saw or square, high-resonance LPF (~18 dB/oct), filter env decay 100–300 ms, env amount high, accent = more env, slide = glide on tied notes.","Resonance + envelope depth; accent and slide as performance",2,"TB-303")
t(f,"Moog Bass","mono","Saw + square an octave apart, 24 dB ladder LPF, cutoff lowish, filter env short decay, slight drive.","Two-osc stacking; ladder filter slope; drive",1,"Minimoog")
t(f,"Reese Bass","mono","Two saws detuned 10–30 cents, little or no filter movement, the beat frequency is the sound. Often chorus or phaser later.","Detune as motion; beating",1,"Reese Project / jungle, DnB")
t(f,"Wobble Bass","mono","Saw or square, LPF with LFO on cutoff synced to tempo (1/4–1/16), high resonance, distortion after.","LFO as rhythmic modulation; tempo sync",2,"dubstep")
t(f,"Neuro Bass","mono","FM or wavetable with heavy saturation, resampled and re-filtered; movement from several slow LFOs on different targets.","Layered modulation; resampling as a technique",3,"neurofunk DnB")
t(f,"FM Bass","mono","Two operators 1:1, modulator index with a short envelope, carrier sine, no filter.","FM index envelope as timbral pluck",2,"DX7 'Bass 1'")
t(f,"Pluck Bass","mono","Saw, LPF, filter env very short decay, amp env short too; velocity → filter.","Shortest envelopes; velocity routing",1,"")
t(f,"Synthwave Bass","mono","Square, LPF closed-ish, amp env short decay no sustain, sequenced 16ths, slight chorus.","Gated sequences; pulse body",1,"outrun")
t(f,"PWM Bass","mono","Pulse with LFO on width (slow), LPF, held notes.","Pulse-width modulation",2,"SH-101")
