t(f,"Growl Bass","mono","Saw into a formant or band-pass with LFO/env on vowel position, drive.","Formant filtering; vowel movement",3,"")
t(f,"Donk","mono","Sine or triangle with a pitch env (fast drop), very short decay, hard; plus a filter ping.","Pitch env + decay = 'donk'",2,"UK bounce")
t(f,"Hoover Bass","mono","Detuned saws with pitch sweep down into the note, PWM-ish, chorus. The hoover in the bass register.","Pitch sweep; detune stack",2,"Mentasm / Alpha Juno")
