bad=[(x["name"],t_) for x in C for t_ in x["templates"] if t_ not in allids]
assert not bad, bad
for v in F.values():
    for i in v["items"]: i["concepts"]=[x["name"] for x in C if i["id"] in x["templates"]]

out = {"title":"Synth Templates — catalog of candidates","born":"2026-10-29","families":[{"name":k,"note":v["note"],"items":v["items"]} for k,v in F.items()],"concepts":C}
n = sum(len(v["items"]) for v in F.values())
json.dump(out, open("catalog.json","w"), indent=1)
print(n, "templates across", len(F), "families;", len(C), "concepts mapped")
